'use strict';
let drawingDraft=null;
const DRAW_FONTS={'Sans serif':'Segoe UI, sans-serif','Serif':'Georgia, serif','Monospace':'Consolas, monospace'};
const isHex=c=>typeof c==='string'&&/^#[0-9a-f]{6}$/i.test(c);
function validAnnotation(a){return a&&typeof a.id==='string'&&['rect','text'].includes(a.kind)&&finitePoint(a)&&Number.isFinite(a.width)&&a.width>=10&&a.width<=10000&&Number.isFinite(a.height)&&a.height>=10&&a.height<=10000&&isHex(a.color)&&Number.isFinite(a.strokeWidth)&&a.strokeWidth>=1&&a.strokeWidth<=12&&['solid','dashed','dotted'].includes(a.lineStyle)&&(a.fill==='none'||isHex(a.fill))&&typeof a.text==='string'&&a.text.length<=10000&&Number.isFinite(a.fontSize)&&a.fontSize>=8&&a.fontSize<=96&&Object.hasOwn(DRAW_FONTS,a.fontFamily)&&['left','center','right'].includes(a.align)&&['bold','italic','underline'].every(k=>typeof a[k]==='boolean');}
function makeAnnotation(kind,p){return {id:uid(),kind,...snapPoint(p),width:kind==='text'?240:10,height:kind==='text'?60:10,color:'#547b68',strokeWidth:2,lineStyle:'solid',fill:'none',text:kind==='text'?'Texte libre':'',fontSize:18,fontFamily:'Sans serif',align:'left',bold:false,italic:false,underline:false};}
function drawingBounds(a,start,end){a.x=Math.min(start.x,end.x);a.y=Math.min(start.y,end.y);a.width=Math.min(10000,Math.max(GRID,Math.abs(end.x-start.x)));a.height=Math.min(10000,Math.max(GRID,Math.abs(end.y-start.y)));}
function annotationSvg(a,draft=false){
  const selectedClass=isSelected('annotation',a.id)?'drawing-selected':'';
  const dash=a.lineStyle==='dashed'?'10 6':a.lineStyle==='dotted'?'2 5':'';
  const label=a.kind==='rect'?'Rectangle':'Texte : '+a.text.slice(0,60);
  let body;
  if(a.kind==='rect')body=`<rect class="drawing-rect" x="${a.x}" y="${a.y}" width="${a.width}" height="${a.height}" stroke="${a.color}" stroke-width="${a.strokeWidth}" stroke-dasharray="${dash}" fill="${a.fill}" fill-opacity="0.2"/>`;
  else {const x=a.x+(a.align==='center'?a.width/2:a.align==='right'?a.width:0);body=`<text class="drawing-text" x="${x}" y="${a.y+a.fontSize}" fill="${a.color}" font-family="${DRAW_FONTS[a.fontFamily]}" font-size="${a.fontSize}" font-weight="${a.bold?'700':'400'}" font-style="${a.italic?'italic':'normal'}" text-decoration="${a.underline?'underline':'none'}" text-anchor="${a.align==='center'?'middle':a.align==='right'?'end':'start'}" xml:space="preserve">${a.text.split('\n').map((line,i)=>`<tspan x="${x}" dy="${i?a.fontSize*1.35:0}">${esc(line||' ')}</tspan>`).join('')}</text>`;}
  return `<g ${draft?'':`data-annotation="${esc(a.id)}"`} class="${selectedClass} ${draft?'drawing-draft':''}" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${a.kind==='text'?`<rect class="text-hit" x="${a.x}" y="${a.y}" width="${a.width}" height="${a.height}" fill="transparent"/>`:''}${body}</g>`;
}
function renderAnnotations(){
  $('#drawings').innerHTML=(project.annotations||[]).map(a=>annotationSvg(a)).join('')+(drawingDraft?annotationSvg(drawingDraft.annotation,true):'');
  const a=selected?.kind==='annotation'&&(project.annotations||[]).find(a=>a.id===selected.id);
  $('#drawing-handles').innerHTML=a?`<rect class="drawing-bounds" x="${a.x}" y="${a.y}" width="${a.width}" height="${a.height}"/><rect class="drawing-resize" data-resize-annotation="${esc(a.id)}" x="${a.x+a.width-5}" y="${a.y+a.height-5}" width="10" height="10"><title>Redimensionner ${a.kind==='rect'?'le rectangle':'la zone de texte'}</title></rect>`:'';
  if(drag?.kind==='marquee'){const s=drag.start,e=drag.end;$('#drawing-handles').insertAdjacentHTML('beforeend',`<rect class="selection-marquee" x="${Math.min(s.x,e.x)}" y="${Math.min(s.y,e.y)}" width="${Math.abs(s.x-e.x)}" height="${Math.abs(s.y-e.y)}"/>`);}
}
function annotationInspector(a){return `<div class="selection-header"><span class="component-icon">${a.kind==='rect'?'▭':'T'}</span><div><strong>${a.kind==='rect'?'Rectangle':'Texte libre'}</strong><small>Dessin indépendant des composants</small></div></div>${a.kind==='text'?`<label class="field">Texte<textarea data-drawing-prop="text" maxlength="10000" rows="4">${esc(a.text)}</textarea></label><label class="field">Police<select data-drawing-prop="fontFamily">${options(Object.keys(DRAW_FONTS),a.fontFamily)}</select></label><label class="field">Taille (px)<input data-drawing-prop="fontSize" type="number" min="8" max="96" value="${a.fontSize}"></label><div class="text-format">${[['bold','Gras','B'],['italic','Italique','I'],['underline','Souligné','U']].map(([key,label,glyph])=>`<button class="button" data-drawing-toggle="${key}" aria-label="${label}" aria-pressed="${a[key]}">${glyph}</button>`).join('')}</div><label class="field">Alignement<select data-drawing-prop="align"><option value="left" ${a.align==='left'?'selected':''}>Gauche</option><option value="center" ${a.align==='center'?'selected':''}>Centré</option><option value="right" ${a.align==='right'?'selected':''}>Droite</option></select></label>`:`<label class="field">Type de trait<select data-drawing-prop="lineStyle"><option value="solid" ${a.lineStyle==='solid'?'selected':''}>Continu</option><option value="dashed" ${a.lineStyle==='dashed'?'selected':''}>Tirets</option><option value="dotted" ${a.lineStyle==='dotted'?'selected':''}>Pointillés</option></select></label><label class="field">Épaisseur (px)<input data-drawing-prop="strokeWidth" type="number" min="1" max="12" value="${a.strokeWidth}"></label><label class="drawing-check"><input type="checkbox" data-drawing-toggle="filled" ${a.fill!=='none'?'checked':''}> Remplissage léger</label>${a.fill!=='none'?`<label class="field">Couleur du fond<input data-drawing-prop="fill" type="color" value="${a.fill}"></label>`:''}`}<label class="field">${a.kind==='rect'?'Couleur du trait':'Couleur du texte'}<input data-drawing-prop="color" type="color" value="${a.color}"></label><div class="drawing-dimensions">${['width','height'].map(k=>`<label class="field">${k==='width'?'Largeur':'Hauteur'}<input data-drawing-prop="${k}" type="number" min="10" max="10000" step="10" value="${a[k]}"></label>`).join('')}</div><button class="button full" id="remove-drawing">Supprimer le dessin</button><p class="inspector-note">Glissez le dessin avec l’outil Sélection. La poignée en bas à droite permet de le redimensionner. Les dessins sont sauvegardés avec le projet.</p>`;}
function drawingPointerDown(event,p){
  const resize=event.target.closest('[data-resize-annotation]'),el=event.target.closest('[data-annotation]');
  if(mode==='rect'){const start=snapPoint(p);drawingDraft={start,annotation:makeAnnotation('rect',start)};drag={kind:'draw-rect',changed:false};selected=null;renderAnnotations();renderWires();renderInspector();return true;}
  if(mode==='text'){mutate(()=>{const a=makeAnnotation('text',p);project.annotations??=[];project.annotations.push(a);selected={kind:'annotation',id:a.id};});setMode('select');return true;}
  if(resize||el){const id=resize?.dataset.resizeAnnotation||el.dataset.annotation,a=project.annotations.find(a=>a.id===id);selected={kind:'annotation',id};drag={kind:resize?'resize-drawing':'move-drawing',id,start:snapPoint(p),baseline:clone(a),changed:false};renderAnnotations();renderBlocks();renderWires();renderInspector();return true;}
  return false;
}
function drawingPointerMove(p){
  p=snapPoint(p);
  if(drag?.kind==='draw-rect'){drawingBounds(drawingDraft.annotation,drawingDraft.start,p);drag.changed=p.x!==drawingDraft.start.x||p.y!==drawingDraft.start.y;renderAnnotations();return true;}
  if(!['move-drawing','resize-drawing'].includes(drag?.kind))return false;
  const a=project.annotations.find(a=>a.id===drag.id),base=drag.baseline,dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(!a)return true;
  if(!drag.changed&&(dx||dy)){checkpoint();drag.changed=true;}
  if(drag.kind==='move-drawing'){a.x=base.x+dx;a.y=base.y+dy;}else {a.width=Math.min(10000,Math.max(10,base.width+dx));a.height=Math.min(10000,Math.max(10,base.height+dy));}
  renderAnnotations();return true;
}
function finishDrawing(){if(drag?.kind!=='draw-rect')return false;const draft=drawingDraft;drawingDraft=null;drag=null;if(draft){mutate(()=>{project.annotations??=[];project.annotations.push(draft.annotation);selected={kind:'annotation',id:draft.annotation.id};});setMode('select');}return true;}
function setupDrawingTools(){
  let editField=null;
  $('#inspector-content').addEventListener('input',event=>{const el=event.target,key=el.dataset.drawingProp;if(!key||!el.matches('input,textarea'))return;const a=(project.annotations||[]).find(a=>a.id===selected?.id);if(!a)return;const value=['fontSize','strokeWidth','width','height'].includes(key)?Number(el.value):el.value,next={...a,[key]:value};if(!validAnnotation(next))return;if(editField!==el){checkpoint();editField=el;}a[key]=value;save();renderAnnotations();$('#undo').disabled=!past.length;$('#redo').disabled=!future.length;});
  $('#inspector-content').addEventListener('focusout',()=>editField=null);
  $('#inspector-content').addEventListener('change',event=>{const el=event.target,key=el.dataset.drawingProp,a=(project.annotations||[]).find(a=>a.id===selected?.id);if(!a)return;if(key&&el.matches('select'))mutate(()=>a[key]=el.value);if(key&&el.matches('input')&&!validAnnotation({...a,[key]:['fontSize','strokeWidth','width','height'].includes(key)?Number(el.value):el.value})){el.value=a[key];toast('Valeur de format invalide.');}if(el.dataset.drawingToggle==='filled')mutate(()=>a.fill=el.checked?'#dbe9df':'none');});
  $('#inspector-content').addEventListener('click',event=>{if(event.target.id==='remove-drawing'){removeSelected();return;}const key=event.target.dataset.drawingToggle;if(!['bold','italic','underline'].includes(key))return;const a=(project.annotations||[]).find(a=>a.id===selected?.id);if(a)mutate(()=>a[key]=!a[key]);});
}
